changeSet.sql:
-- Покрывающий индекс для фильтра по игрокам (SELECT match_id по player_id).
CREATE INDEX IF NOT EXISTS match_player_player_match_idx ON match_player (player_id, match_id);
-- Старый одноколоночный индекс полностью покрывается новым составным.
DROP INDEX IF EXISTS match_player_player_idx;

-- Стабильная сортировка кадров по дате создания (tie-breaker в ТОПе и списках).
CREATE INDEX IF NOT EXISTS screenshot_created_idx ON screenshot (created_at DESC);

-- После массового импорта/переиндексации обновляем статистику планировщика.
ANALYZE app_user;
ANALYZE club;
ANALYZE player;
ANALYZE archive_session;
ANALYZE match;
ANALYZE match_player;
ANALYZE screenshot;
ANALYZE screenshot_like;
ANALYZE screenshot_share;
ANALYZE screenshot_comment;
